                    if (error) newErrors[key] = error;
                });

                setErrors(newErrors);
                setTouched({ fullName: true, email: true, phone: true });

                if (Object.keys(newErrors).length === 0) {
                    setIsSubmitted(true);
                    console.log('Form submitted:', formData);
                }
            };

            if (isSubmitted) {
                return (
                    <div className="max-w-md mx-auto mt-10 p-6 bg-slate-800 rounded-lg shadow-xl text-center">
