                                className={`w-full px-4 py-2 rounded bg-slate-900 border ${errors.fullName ? 'border-red-500' : 'border-slate-600'} focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all`}
                                placeholder="John Doe"
                            />
