                                id="email"
                                name="email"
                                value={formData.email}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                required
                                aria-required="true"
                                aria-invalid={errors.email ? "true" : "false"}
                                aria-describedby={errors.email ? "email-error" : null}
                                className={`w-full px-4 py-2 rounded bg-slate-900 border ${errors.email ? 'border-red-500' : 'border-slate-600'} focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all`}
                                placeholder="john@example.com"
                            />
                            {errors.email && (
