                                id="phone"
                                name="phone"
                                value={formData.phone}
                                onChange={handleChange}
                                onBlur={handleBlur}
                                aria-invalid={errors.phone ? "true" : "false"}
                                aria-describedby="phone-helper phone-error"
                                className={`w-full px-4 py-2 rounded bg-slate-900 border ${errors.phone ? 'border-red-500' : 'border-slate-600'} focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all`}
                                placeholder="+1 234 567 8900"
                            />
                            <p id="phone-helper" className="helper-text">Expected format: +1 234 567 8900 (min 10 digits)</p>
